const modelSpanishMessages: Record<string, string> = {};
const addModelMessage = (key: string, value: string) => {
  if (key in en) modelSpanishMessages[key] = value;
};

for (const table of PERFORMANCE_TABLES) {
  const prefix = `table.${table.id}`;
  addModelMessage(`${prefix}.help.purpose`, table.help.purpose);
  table.help.glossary.forEach((item, index) => addModelMessage(`${prefix}.help.glossary.${index}.meaning`, item.meaning));
  table.help.steps.forEach((step, index) => addModelMessage(`${prefix}.help.steps.${index}`, step));
  table.help.tips.forEach((tip, index) => addModelMessage(`${prefix}.help.tips.${index}`, tip));
  if (table.kind === 'figure') {
    table.cautions?.forEach((value, index) => addModelMessage(`${prefix}.cautions.${index}`, value));
    table.uncertain?.forEach((value, index) => addModelMessage(`${prefix}.uncertain.${index}`, value));
  } else if (table.kind === 'holding') {
    table.sourceRemarks.forEach((value, index) => addModelMessage(`${prefix}.sourceRemarks.${index}`, value));
  } else if (table.kind === 'flight-planning') {
    table.gaps.forEach((gap, index) => addModelMessage(`${prefix}.gaps.${index}.note`, gap.note));
  }
}

